var config = new ProducerConfig
{
    BootstrapServers = "broker-1:9092,broker-2:9092",
    Acks = Acks.All, // Wait for all in-sync replicas
    Lingerms = 5, // Batch small messages for up to 5ms
    BatchSize = 16384, // 16 KB batch size
    CompressionType = CompressionType.Lz4,
    EnableIdempotence = true, // Safe retries without duplicates
    MaxInFlight = 5, // Retries without reordering (requires idempotence)
    Retries = int.MaxValue
};

using var producer = new ProducerBuilder<string, string>(config).Build();

var config = new ConsumerConfig
{
    BootstrapServers = "broker-1:9092,broker-2:9092",
    GroupId = "payment-processors",
    AutoOffsetReset = AutoOffsetReset.Earliest,
    EnableAutoCommit = false, // Manual commit for safety
    MaxPollIntervalMs = 300000, // 5 minutes
    SessionTimeoutMs = 30000, // 30 seconds
    EnablePartitionEof = true
};

using var consumer = new ConsumerBuilder<string, string>(config).Build();
consumer.Subscribe("payments");
